INSERT INTO `mdc_notice` (`id`, `task_id`, `title`, `content`, `msg_category`, `author`, `url`, `created_by`, `created_at`, `updated_by`, `updated_at`) VALUES (144905376160287968, 144905376160287965, '中国版权保护中心（中华版权代理中心）简介', '<p><span style=\"font-size: 16px\">&nbsp; &nbsp; &nbsp; 中国版权保护中心成立于1998年9月，作为国家级版权保护和服务机构，坚持以学术引领、技术支撑和服务赋能为己任，积极服务国家经济、科技和文化繁荣发展大局，承担各类作品和计算机软件版权登记职责，是我国唯一的计算机软件版权登记、版权质权登记机构。开展版权鉴定、监测维权、版权文化研究、版权资产评估管理、版权领域标准制定宣贯和版权业务培训等专项服务。累计完成版权登记1300余万件，其中计算机软件版权登记超过1000万件，作品版权登记近300万件。管理中华版权服务有限公司和《中国版权》杂志社有限公司等多家下属机构，主办《中国版权》《创意中国》杂志。</span></p><p style=\"line-height: 28px; text-align: justify\"><span style=\"font-size: 16px\">&nbsp; &nbsp; &nbsp; 中国版权保护中心深入学习贯彻习近平新时代中国特色社会主义思想，坚持立足新发展阶段，完整、准确、全面贯彻新发展理念，构建新发展格局，秉持服务经济主战场、服务科技创造创新、服务文化繁荣发展、服务人民美好生活、服务创作人权益的“五个服务”理念，在版权全链条中努力做强保护、做优服务。</span></p><p style=\"line-height: 28px; text-align: justify\"><span style=\"font-size: 16px\">&nbsp; &nbsp; &nbsp; 近年来，中国版权保护中心在优化提升版权登记核心业务的基础上，坚持守正创新，不断提高版权维权和法律服务水平，促进版权贸易和版权价值挖掘，开展面向数字时代互联网空间清朗治理的版权工作；推进版权历史文化和学术研究，主动设置议题开展版权国际交流，积极参与版权领域全球治理；围绕作品、产品、衍生品“三品”逻辑，搭建自动赋权、登记确权、交易授权、纠纷维权、规则护权“五权”理论架构，形成中国版权保护“三品五权”理论框架体系，积极发挥版权服务人民、服务社会和服务产业发展的重要作用。</span></p><p style=\"line-height: 28px; text-align: justify\"><span style=\"font-size: 16px\">&nbsp; &nbsp; &nbsp; 版权是文化的内核，版权是创意的化身。</span></p><p style=\"line-height: 28px; text-align: justify\"><span style=\"font-size: 16px\">&nbsp; &nbsp; &nbsp; 新时代新征程，中国版权保护中心全面贯彻落实党的二十大精神，推进版权保护和服务工作高质量发展，助力文化数字化和数字经济发展，布局新兴数字领域版权标准和规则设立，创新版权纠纷专业调解机制。坚定文化自信，弘扬版权历史文化，深化版权学术研究，积极应用新技术，大力开展高层次专业化版权人才培养，推进版权强国建设，为社会主义文化强国建设贡献版权力量。</span></p><p><strong>关于我们</strong></p><ul class=\"tight\" data-tight=\"true\"><li><p><a target=\"\" rel=\"noopener noreferrer nofollow\" href=\"https://www.ccopyright.com.cn/index.php?optionid=992\">中心简介</a></p></li><li><p><a target=\"\" rel=\"noopener noreferrer nofollow\" href=\"https://www.ccopyright.com.cn/index.php?optionid=993\">机构设置</a></p></li><li><p><a target=\"\" rel=\"noopener noreferrer nofollow\" href=\"https://www.ccopyright.com.cn/index.php?optionid=1652\">直属企业</a></p></li><li><p><a target=\"\" rel=\"noopener noreferrer nofollow\" href=\"https://www.ccopyright.com.cn/index.php?optionid=1634\">联系我们</a></p></li></ul><p><strong>用户指南</strong></p><ul class=\"tight\" data-tight=\"true\"><li><p><a target=\"\" rel=\"noopener noreferrer nofollow\" href=\"https://www.ccopyright.com.cn/index.php?optionid=1003\">登记指南</a></p></li><li><p><a target=\"\" rel=\"noopener noreferrer nofollow\" href=\"https://www.ccopyright.com.cn/index.php?optionid=1004\">用户帮助中心</a></p></li></ul><p><strong>版权登记</strong></p><ul class=\"tight\" data-tight=\"true\"><li><p><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"https://register.ccopyright.com.cn/registration.html#/registerSoft\">软件登记</a></p></li><li><p><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"https://register.ccopyright.com.cn/registration.html#/registerOpus\">作品登记</a></p></li><li><p><a target=\"\" rel=\"noopener noreferrer nofollow\" href=\"https://www.ccopyright.com.cn/?optionid=1650\">数字登记</a></p></li></ul><p><strong>登记公告</strong></p><ul class=\"tight\" data-tight=\"true\"><li><p><a target=\"\" rel=\"noopener noreferrer nofollow\" href=\"https://register.ccopyright.com.cn/publicInquiry.html?type=softList\">软件公告</a></p></li><li><p><a target=\"\" rel=\"noopener noreferrer nofollow\" href=\"https://register.ccopyright.com.cn/publicInquiry.html?type=opusList\">作品公告</a></p></li><li><p><a target=\"\" rel=\"noopener noreferrer nofollow\" href=\"https://www.ccopyright.com/\">数字公告</a></p></li></ul><h3 style=\"line-height: 21px\">联系我们</h3><p style=\"line-height: 25px\"><span style=\"font-size: 12px\">地址：北京市丰台区汽车博物馆西路9号院6号楼<br>软件著作权咨询电话：010-61090099<br>作品著作权咨询电话：010-61092299<br>综合咨询电话：010-68003887<br>电话：010-83771600(总机)<br>邮编：100070</span></p>', 2, '阿是大V ', NULL, 680083598598475778, '2026-10-11 14:31:19.861', 680083598598475778, '2026-10-11 14:31:19.861');
